import java.io.*;
import java.util.*;

public class TwentyFive {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        String pattern = sc.next();
        int totalMatches = 0;
        for (int num = 0; num < 100000000; num += 25) {
            String candidate = String.valueOf(num);
            if (candidate.length() != pattern.length()) continue;
            int xCode = -1;
            boolean valid = true;
            for (int index = 0; index < pattern.length(); index++) {
                char pChar = pattern.charAt(index);
                char cChar = candidate.charAt(index);
                if (pChar == 'X') {
                    if (xCode == -1) {
                        xCode = cChar;
                    }
                    if (cChar != xCode) {
                        valid = false;
                        break;
                    }
                } else if (pChar != '_') {
                    if (cChar != pChar) {
                        valid = false;
                        break;
                    }
                }
            }
            if (valid) totalMatches++;
        }
        System.out.println(totalMatches);
        sc.close();
    }
}
